"""Build the unpublished 1SW Week 4 teacher/student Canvas module."""

import asyncio, json, mimetypes, re, sys
from pathlib import Path
import httpx

BASE="https://learn.irvingisd.net"; COURSE_ID=98060
MODULE_NAME="1SW Wk4: Tech Support Careers and MakeCode"
ROOT=Path(__file__).resolve().parents[2]; TEMPLATES=Path(__file__).parent/"templates"; ASSETS=ROOT/"cce-curriculum/resources/canvas-licensed/1sw/wk4"

def slugify(v): return re.sub(r"[^a-z0-9]+","-",v.lower().replace("&","and")).strip("-")
async def api(c,m,p,**kw):
    r=await c.request(m,f"{BASE}/api/v1{p}",**kw); r.raise_for_status(); return r.json() if r.content else None
async def paged(c,p,params=None):
    out=[]; url=f"{BASE}/api/v1{p}"; q={"per_page":100,**(params or {})}
    while url:
        r=await c.get(url,params=q); r.raise_for_status(); out+=r.json(); url=r.links.get("next",{}).get("url"); q=None
    return out
async def ensure_module(c):
    prior_name="1SW Wk4: Help Desk Heroes - Tech Support Careers and MakeCode"
    modules=await paged(c,f"/courses/{COURSE_ID}/modules"); found=next((m for m in modules if m["name"] in {MODULE_NAME,prior_name}),None)
    if found: return await api(c,"PUT",f"/courses/{COURSE_ID}/modules/{found['id']}",data={"module[name]":MODULE_NAME,"module[published]":"false"})
    return await api(c,"POST",f"/courses/{COURSE_ID}/modules",data={"module[name]":MODULE_NAME,"module[published]":"false"})
async def ensure_folder(c,path):
    current=""; folder=None
    for name in path.split("/")[1:]:
        target=f"{current}/{name}".strip("/"); enc=httpx.URL("/"+target).raw_path.decode("ascii").lstrip("/")
        r=await c.get(f"{BASE}/api/v1/courses/{COURSE_ID}/folders/by_path/{enc}")
        if r.status_code==200 and r.json(): folder=r.json()[-1]
        else: folder=await api(c,"POST",f"/courses/{COURSE_ID}/folders",data={"name":name,"parent_folder_path":"course files"+(f"/{current}" if current else ""),"locked":"true"})
        current=target
    if folder and not folder.get("locked"): folder=await api(c,"PUT",f"/folders/{folder['id']}",data={"locked":"true"})
    return folder
async def upload(c,path,folder):
    init=await api(c,"POST",f"/courses/{COURSE_ID}/files",data={"name":path.name,"parent_folder_path":folder,"on_duplicate":"overwrite"})
    r=await c.post(init["upload_url"],data=init["upload_params"],files={"file":(path.name,path.read_bytes(),mimetypes.guess_type(path.name)[0] or "application/octet-stream")},follow_redirects=True); r.raise_for_status(); return r.json()
async def find_file(c,name):
    files=await paged(c,f"/courses/{COURSE_ID}/files",{"search_term":name}); match=next((f for f in files if f.get("display_name")==name),None)
    if not match: raise ValueError(f"Canvas file not found: {name}")
    return match
def render(name,values):
    text=(TEMPLATES/name).read_text()
    for k,v in values.items(): text=text.replace("{{"+k+"}}",str(v))
    unresolved=sorted(set(re.findall(r"\{\{[^}]+\}\}",text)))
    if unresolved: raise ValueError(f"Unresolved values in {name}: {unresolved}")
    return text
async def upsert_page(c,title,body,url):
    data={"wiki_page[title]":title,"wiki_page[body]":body,"wiki_page[published]":"false","wiki_page[editing_roles]":"teachers"}; r=await c.get(f"{BASE}/api/v1/courses/{COURSE_ID}/pages/{url}")
    if r.status_code==200: return await api(c,"PUT",f"/courses/{COURSE_ID}/pages/{url}",data=data)
    if r.status_code!=404: r.raise_for_status()
    return await api(c,"POST",f"/courses/{COURSE_ID}/pages",data=data)
async def upsert_item(c,module_id,page,title):
    items=await paged(c,f"/courses/{COURSE_ID}/modules/{module_id}/items"); item=next((i for i in items if i.get("page_url")==page["url"]),None)
    if item: return await api(c,"PUT",f"/courses/{COURSE_ID}/modules/{module_id}/items/{item['id']}",data={"module_item[title]":title})
    return await api(c,"POST",f"/courses/{COURSE_ID}/modules/{module_id}/items",data={"module_item[type]":"Page","module_item[page_url]":page["url"],"module_item[title]":title})
def flow(color,title,text): return f'<div style="border-left:5px solid {color};padding-left:16px;margin:18px 0"><h4 style="margin:0;color:{color}">{title}</h4><p>{text}</p></div>'

async def main():
    token=sys.stdin.readline().strip()
    if not token: raise SystemExit("Canvas token required on stdin")
    async with httpx.AsyncClient(headers={"Authorization":f"Bearer {token}"},timeout=120) as c:
        module=await ensure_module(c); module_id=module["id"]
        support_names={
          "CARDS":"wk4-it-support-career-cards.pdf","D1":"wk4-day1-career-interest-check.pdf","ROUTE":"wk4-route-data-guide.pdf","COMPARE":"wk4-education-pathway-comparison.pdf","COMPARE_BI":"wk4-education-pathway-comparison-bilingual.pdf","MODEL":"wk4-education-pathway-comparison-model.pdf","D2":"wk4-day2-route-decision.pdf","SCENARIOS":"wk4-help-desk-scenario-cards.pdf","STARTER":"wk4-makecode-starter-blocks.pdf","SORT":"wk4-troubleshooting-step-sort-cards.pdf","SORT_BI":"wk4-troubleshooting-step-sort-cards-bilingual.pdf","PROGRAM":"wk4-help-desk-program-evidence.pdf","E3":"1sw-wk4-day3-help-desk-simulator-makecode-day-1.pdf","ROLE":"wk4-help-desk-role-play-script.pdf","ROLE_BI":"wk4-help-desk-role-play-script-bilingual.pdf","CLIPBOARD":"clipboard-roster-grid.pdf","D4":"wk4-day4-customer-service-check.pdf","RUBRIC":"wk4-demo-rubric.pdf","CONNECTION":"wk4-day5-xello-skill-connection.pdf"}
        support_folder="course files/CCR Materials/1SW/Wk4"; await ensure_folder(c,support_folder); files={}
        for key,name in support_names.items():
            source_dir=ROOT/"docs/resources/exit-tickets" if name.startswith("1sw-") else ROOT/"docs/resources/worksheets"
            files[key]=await upload(c,source_dir/name,support_folder)
        files["X_INTERESTS"]=await find_file(c,"interests.pdf"); files["X_SKILLS"]=await find_file(c,"about-me.pdf")
        uploads={}; folders={}
        for day in range(1,6):
            folder_path=f"course files/CCR Materials/1SW/Wk4/Day {day} Visuals"; folders[day]=await ensure_folder(c,folder_path); uploads[day]={}
            day_dir=ASSETS/f"day{day}"
            if day_dir.exists():
                for path in sorted(day_dir.glob("*.png")): uploads[day][path.name]=await upload(c,path,folder_path)
        student_values={
          1:{"PROGRAM_IMAGE_ID":uploads[1]["irving-it-programs.png"]["id"],"APP_IMAGE_ID":uploads[1]["it-app-exploration.png"]["id"],"CARDS_FILE_ID":files["CARDS"]["id"],"CHECK_FILE_ID":files["D1"]["id"]},
          2:{"IBC_IMAGE_ID":uploads[2]["ibc-explainer.png"]["id"],"GUIDE_IMAGE_ID":uploads[2]["route-data-guide.png"]["id"],"GUIDE_FILE_ID":files["ROUTE"]["id"],"COMPARE_FILE_ID":files["COMPARE"]["id"],"COMPARE_BI_FILE_ID":files["COMPARE_BI"]["id"],"MODEL_FILE_ID":files["MODEL"]["id"],"DECISION_FILE_ID":files["D2"]["id"]},
          3:{"SCENARIO_IMAGE_ID":uploads[3]["help-desk-scenarios.png"]["id"],"STARTER_IMAGE_ID":uploads[3]["makecode-block-order-guide.png"]["id"],"SCENARIO_FILE_ID":files["SCENARIOS"]["id"],"STARTER_FILE_ID":files["STARTER"]["id"],"SORT_FILE_ID":files["SORT"]["id"],"SORT_BI_FILE_ID":files["SORT_BI"]["id"],"EVIDENCE_FILE_ID":files["PROGRAM"]["id"],"EXIT_FILE_ID":files["E3"]["id"]},
          4:{"ROLE_IMAGE_ID":uploads[4]["role-play-script.png"]["id"],"ROLE_FILE_ID":files["ROLE"]["id"],"ROLE_BI_FILE_ID":files["ROLE_BI"]["id"],"CHECK_FILE_ID":files["D4"]["id"]},
          5:{"RUBRIC_IMAGE_ID":uploads[5]["help-desk-evidence-rubric.png"]["id"],"RUBRIC_FILE_ID":files["RUBRIC"]["id"],"CONNECTION_FILE_ID":files["CONNECTION"]["id"]}}
        student_titles={1:"STUDENT: 1SW Wk4 Day 1 - IT Support Careers and Interests",2:"STUDENT: 1SW Wk4 Day 2 - Compare Education Routes",3:"STUDENT: 1SW Wk4 Day 3 - Build a Help Desk Sequence",4:"STUDENT: 1SW Wk4 Day 4 - Test and Role-Play",5:"STUDENT: 1SW Wk4 Day 5 - Add Skills and Submit Evidence"}
        teacher_data={
          1:{"TITLE":"IT Support Careers + Xello Add Interests","SUBTITLE":"50 minutes - TEKS d(1)(C), d(2)(A)","ALERT":"<strong>Required Xello spine:</strong> protect 15 minutes for Add Interests. H&amp;L is optional exploration; the career cards are the equal required route.","PREP":f'<ul><li>Print/post the <a href="/courses/{COURSE_ID}/files/{files["CARDS"]["id"]}/preview">IT Support Career Cards</a> and <a href="/courses/{COURSE_ID}/files/{files["D1"]["id"]}/preview">career/interest check</a>.</li><li>Check Xello rosters and open the licensed <a href="/courses/{COURSE_ID}/files/{files["X_INTERESTS"]["id"]}/preview">My Interests teacher guide</a>.</li><li>Open FYF pp. 36 and 38.</li></ul>',"EVIDENCE":"<p>Required completion evidence: at least one Xello interest in the Completion Standards report. The career/interest check is formative or one coherent minor option; platform access itself is not graded.</p>","FLOW":flow("#5a2d91","Technology-help warm-up - 5 minutes","Name the problem, helper, and diagnostic action.")+flow("#4a9d2f","Four-role comparison - 20 minutes","Use career cards; choose two roles for the check.")+flow("#1f617a","Xello Add Interests - 15 minutes","Add/update at least one interest and review how it appears in About Me.")+flow("#e3ad19","Career-interest evidence - 10 minutes","Use a task and preparation fact, then connect one interest."),"MONITOR":"<p>Help Desk: first-line tickets and escalation. Support Specialist: deeper user/device support. Desktop Support: setup/repair/equipment. Systems Administrator: accounts, servers, permissions, backups. Accept different preparation paths when the student uses the card wording and avoids guarantees.</p>","SUPPORT":"<p>Pre-teach support, technician, administrator, certification, preparation, and transferable. Students may circle a task and skill before writing; allow oral rehearsal and an English/Spanish vocabulary bank.</p>","FALLBACK":"<p>The career cards replace H&amp;L completely. If Xello is unavailable, record the issue, complete the paper reflection with a current interest, and move required completion to the next Xello catch-up block.</p>"},
          2:{"TITLE":"Certification, Associate, and Bachelor Routes","SUBTITLE":"50 minutes - TEKS d(2)(A), d(2)(B)","ALERT":"<strong>Use the dated guide, not open search.</strong> Vendor prices, exam names, and roadmaps drift. BLS figures are national medians, not starting or DFW salaries.","PREP":f'<ul><li>Print/post the <a href="/courses/{COURSE_ID}/files/{files["ROUTE"]["id"]}/preview">dated Route Data Guide</a>, <a href="/courses/{COURSE_ID}/files/{files["COMPARE"]["id"]}/preview">comparison</a>, optional <a href="/courses/{COURSE_ID}/files/{files["MODEL"]["id"]}/preview">model</a>, and <a href="/courses/{COURSE_ID}/files/{files["D2"]["id"]}/preview">route decision</a>.</li><li>Open FYF p. 37. Treat current CompTIA exploration as optional only after a student-filter check.</li></ul>',"EVIDENCE":"<p>Formative/minor option: complete three-route comparison plus evidence-based route decision. Cost is not required without a current official source.</p>","FLOW":flow("#5a2d91","Certification warm-up - 5 minutes","Distinguish industry evidence from a degree and from a participation award.")+flow("#4a9d2f","IBC and source lesson - 10 minutes","Model median pay, entry preparation, and the meaning of ‘typical.’")+flow("#1f617a","Three-route comparison - 25 minutes","Complete common preparation, time, 2024 median, and tradeoff.")+flow("#e3ad19","Route decision - 10 minutes","Rank by common program length and recommend with a benefit/tradeoff."),"MONITOR":"<p>Key: user support - some college common or HS plus relevant cert may qualify, $60,340; network support - associate typical, $73,340; software developer - bachelor typical, $133,080. All are May 2024 national medians. A defensible recommendation may vary, but must name a benefit, tradeoff, and employer variation.</p>","SUPPORT":"<p>Use the model column, color-code preparation versus pay, and let students highlight the exact sentence they will copy. Read the decision scenario aloud.</p>","FALLBACK":"<p>The dated guide is the normal no-web route. If BLS or CompTIA is blocked, no evidence changes. An absent student completes the same two printed sheets.</p>"},
          3:{"TITLE":"Help Desk Simulator - Build and Save","SUBTITLE":"50 minutes - TEKS d(4)(B)","ALERT":"<strong>Hardware is optional; durable evidence is required.</strong> Use MakeCode hardware, simulator, or paper trace. Update firmware only when a connection failure and official troubleshooting guidance point to it.","PREP":f'<ul><li>Test makecode.microbit.org on a student-filtered Chromebook and prebuild one working example.</li><li>Print duplicate <a href="/courses/{COURSE_ID}/files/{files["SCENARIOS"]["id"]}/preview">scenario-card sets</a>, the <a href="/courses/{COURSE_ID}/files/{files["STARTER"]["id"]}/preview">block-order guide</a>, <a href="/courses/{COURSE_ID}/files/{files["SORT"]["id"]}/preview">sort cards</a>, and <a href="/courses/{COURSE_ID}/files/{files["PROGRAM"]["id"]}/preview">program evidence</a>.</li><li>Assign one Chromebook per team for Days 3-5 and choose a backup: screenshot, share link, downloaded .hex, or paper trace.</li></ul>',"EVIDENCE":"<p><strong>Minor 3 evidence begins:</strong> Program Evidence supplies Logical Sequence and Program Logic/Testing, 8 of 16 points. The Day 3 branching exit is formative.</p>","FLOW":flow("#5a2d91","Troubleshooting order - 5 minutes","Choose the lowest-risk, fastest check first.")+flow("#4a9d2f","Setup and naming - 10 minutes","Scenario, project name, same Chromebook, hardware/simulator/paper route.")+flow("#1f617a","Build or trace - 25 minutes","On start, three Button A branches, wrap to Step 1, Button B FIXED.")+flow("#e3ad19","Test, save, and exit - 10 minutes","Record tests and backup before the branching exit."),"MONITOR":"<p>Correct logic: step starts at 1; Button A shows the current branch before incrementing; after 3 it returns to 1; Button B independently shows FIXED. Wi-Fi scenario never restarts shared equipment when the evidence points to one device. A paper trace through A four times and B once is equivalent.</p>","SUPPORT":"<p>Use the step-sort cards before code, pair driver/navigator roles, keep the completed example projected, allow screen magnification, and accept spoken step text recorded by the partner.</p>","FALLBACK":"<p>No board: simulator. Site blocked: arrange cards, trace the block-order guide, and have another team initial A/A/A/A/B results. Absent: use the paper route or join the assigned team’s saved project on return.</p>"},
          4:{"TITLE":"Swap Test + Customer Service Role-Play","SUBTITLE":"50 minutes - TEKS d(4)(B)","ALERT":"<strong>Finish core behavior before enhancements.</strong> Today must document one partner-test finding and one revision. Spoken performance has an equal written-chat route.","PREP":f'<ul><li>Confirm teams can reopen the saved project or retrieve the backup.</li><li>Print the <a href="/courses/{COURSE_ID}/files/{files["ROLE"]["id"]}/preview">role-play script</a>, optional <a href="/courses/{COURSE_ID}/files/{files["ROLE_BI"]["id"]}/preview">bilingual support</a>, <a href="/courses/{COURSE_ID}/files/{files["CLIPBOARD"]["id"]}/preview">monitoring roster</a>, and <a href="/courses/{COURSE_ID}/files/{files["D4"]["id"]}/preview">customer-service check</a>.</li></ul>',"EVIDENCE":"<p>Minor 3 evidence adds the documented bug/confusion and revision. Individual role-play observation and the customer-service check are formative.</p>","FLOW":flow("#5a2d91","Customer frustration warm-up - 5 minutes","Separate the technical problem from the communication problem.")+flow("#4a9d2f","Reopen and finish core - 15 minutes","Three steps, wrap behavior, Button B FIXED; optional enhancements last.")+flow("#1f617a","Swap, test, revise - 10 minutes","Silent test, one clear part, one confusion, one documented change.")+flow("#e3ad19","Role-play and check - 20 minutes","Two short role rounds, then the customer-service check."),"MONITOR":"<p>Four rules: acknowledge, plain language, one step at a time, and calm next-step language. Exit key: C. A corrects emotion; B skips acknowledgment and assumes a cause; D abandons the user. Accept a written chat transcript demonstrating the same rules.</p>","SUPPORT":"<p>Use the script for round one, bilingual phrase supports, private/low-volume role-play, and written chat for students who cannot perform publicly. Monitor one observable example per student.</p>","FALLBACK":"<p>Paper teams swap the evidence sheet and trace the buttons. If the saved file is missing, recover the backup or trace it; do not spend the period rebuilding from memory. Absent students complete a written support exchange.</p>"},
          5:{"TITLE":"Lightning Demos + Xello Add Skills","SUBTITLE":"50 minutes - TEKS d(1)(C), d(2)(A), d(4)(B)","ALERT":"<strong>Required Xello spine:</strong> protect 20 minutes for Add Skills. H&amp;L favorites are optional. Return Minor 3 scores privately; do not post team totals.","PREP":f'<ul><li>Check Xello rosters and open the licensed <a href="/courses/{COURSE_ID}/files/{files["X_SKILLS"]["id"]}/preview">About Me teacher guide</a>; use only the Add/Update Skill portion.</li><li>Post the <a href="/courses/{COURSE_ID}/files/{files["RUBRIC"]["id"]}/preview">16-point evidence rubric</a> and print the <a href="/courses/{COURSE_ID}/files/{files["CONNECTION"]["id"]}/preview">individual skill connection</a>.</li><li>Order teams before class and cap each demo at one minute.</li></ul>',"EVIDENCE":"<p><strong>Minor 3:</strong> Program Evidence + individual Xello Skill and Help Desk Connection, 16 points. Required completion evidence: at least one Xello skill in the report. The lightning demo is formative communication practice.</p>","FLOW":flow("#5a2d91","Whole-class lightning demos - 20 minutes","One minute per team: scenario, logic, first-step reason, career/preparation, transferable skill.")+flow("#4a9d2f","Xello Add Skills - 20 minutes","Add/update at least one skill and one real-life example.")+flow("#1f617a","Individual connection and submission - 10 minutes","Connect skill, interest, customer service, and career; attach to team evidence."),"MONITOR":"<p>Do not live-score presentation polish. Minor 3 key: team sequence/logic evidence plus accurate route-guide preparation and an individual skill example. Students may say IT support is not a fit and still earn full evidence credit.</p>","SUPPORT":"<p>Allow one student to operate while another speaks, use a written one-minute script, permit a private teacher explanation, read Xello skill descriptions aloud, and provide skill/example stems.</p>","FALLBACK":"<p>Program site/device failure uses the paper trace. Xello failure is recorded and moves to catch-up while the student completes the reflection with a known skill. An absent student submits a written lightning-demo script or explains it privately.</p>"}}
        contracts={
          1:{"TOPIC":"IT Support Careers","OBJECTIVE":"Students will identify IT support career opportunities and describe common preparation requirements using district HQIM and fixed career evidence.","TEKS":"d(1)(C), d(2)(A)","DOL":"Two-career evidence comparison, one interest-to-task connection, and at least one added or updated Xello interest."},
          2:{"TOPIC":"Education Routes","OBJECTIVE":"Students will research, describe, and evaluate education and training options for IT careers using common preparation, time, pay, and tradeoff evidence from a dated source guide.","TEKS":"d(2)(A), d(2)(B)","DOL":"Three-route comparison and recommendation using an accurate preparation fact, a benefit, and a tradeoff."},
          3:{"TOPIC":"Troubleshooting Logic","OBJECTIVE":"Students will identify problem-solving and communication skills that transfer among careers by building, testing, and explaining a three-step help desk sequence.","TEKS":"d(4)(B)","DOL":"Help Desk Program Evidence with an ordered sequence, Button A/B logic, recorded test, durable backup, and transferable-skill connection."},
          4:{"TOPIC":"Customer Service","OBJECTIVE":"Students will identify communication and problem-solving skills that transfer among careers by testing a support sequence, revising it from feedback, and responding to a frustrated user.","TEKS":"d(4)(B)","DOL":"One partner-test finding, one documented revision, and a customer-service response that follows four support rules and transfers the skill to another career."},
          5:{"TOPIC":"Career Skills","OBJECTIVE":"Students will identify an IT support career and common preparation and explain how one practiced skill transfers among careers using program evidence and their Xello profile.","TEKS":"d(1)(C), d(2)(A), d(4)(B)","DOL":"Team Help Desk Program Evidence, individual Xello Skill and Help Desk Connection, and at least one added or updated Xello skill."}}
        pages={}
        for day in range(1,6):
            st=student_titles[day]; student=await upsert_page(c,st,render(f"wk4-day{day}-student.html",{"COURSE_ID":COURSE_ID,**student_values[day]}),slugify(st))
            tt=f"TEACHER: 1SW Wk4 Day {day} Facilitator Guide"; teacher=await upsert_page(c,tt,render("wk4-teacher.html",{"COURSE_ID":COURSE_ID,"DAY":day,"STUDENT_PAGE_URL":student["url"],**contracts[day],**teacher_data[day]}),slugify(tt))
            await upsert_item(c,module_id,teacher,tt); await upsert_item(c,module_id,student,st); pages[day]={"teacher":teacher,"student":student}
        items=await paged(c,f"/courses/{COURSE_ID}/modules/{module_id}/items"); by_url={i.get("page_url"):i for i in items}
        desired=[]; used=set()
        for day in range(1,6):
            header=next((i for i in items if i.get("type")=="SubHeader" and i.get("title")==f"Day {day}"),None)
            if header: desired.append(header["id"]); used.add(header["id"])
            for page_kind in ("teacher","student"):
                item=by_url[pages[day][page_kind]["url"]]; desired.append(item["id"]); used.add(item["id"])
        desired.extend(i["id"] for i in sorted(items,key=lambda item:item["position"]) if i["id"] not in used)
        for position,item_id in reversed(list(enumerate(desired,start=1))): await api(c,"PUT",f"/courses/{COURSE_ID}/modules/{module_id}/items/{item_id}",data={"module_item[position]":position})
        final=await paged(c,f"/courses/{COURSE_ID}/modules/{module_id}/items"); module=await api(c,"GET",f"/courses/{COURSE_ID}/modules/{module_id}")
        print(json.dumps({"module":{"id":module_id,"published":module["published"]},"folders":{str(d):{"id":f["id"],"locked":f["locked"]} for d,f in folders.items()},"pages":{str(d):{k:{"url":v["url"],"published":v["published"]} for k,v in p.items()} for d,p in pages.items()},"items":[{"id":i["id"],"position":i["position"],"title":i["title"],"page_url":i.get("page_url")} for i in final]},indent=2))

asyncio.run(main())
